-- ISS-12780: the daily retention sweep
-- (`/cron/cleanup-repository-default-observation-receipts`) deletes receipts by
-- `created_at`. Generated by `prisma migrate dev --create-only`, then made a
-- concurrent build because the table is written by every push and
-- pull-request webhook. Keep this as one bare statement so deployment does not
-- block writes or accept an invalid prior index.
-- CreateIndex
CREATE INDEX CONCURRENTLY "repository_default_observation_receipts_created_at_idx" ON "repository_default_observation_receipts"("created_at");
